DROP TABLE IF EXISTS `cargas_historicas_materias_v3`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cargas_historicas_materias_v3` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `carga_historica_id` int(11) NOT NULL,
  `materia_id` int(10) unsigned DEFAULT NULL,
  `especialidad_destino_id` int(10) unsigned DEFAULT NULL,
  `horas_semanal` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `horas_lapso` smallint(5) unsigned NOT NULL DEFAULT 0,
  `seccion` varchar(20) DEFAULT '',
  `cupos` smallint(5) unsigned DEFAULT 0,
  `inscritos` smallint(5) unsigned DEFAULT 0,
  `cohorte` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_hist_materia_id` (`carga_historica_id`),
  KEY `fk_hist_mat_catalogo` (`materia_id`),
  KEY `idx_hist_esp_dest` (`especialidad_destino_id`),
  CONSTRAINT `fk_hist_esp_catalogo` FOREIGN KEY (`especialidad_destino_id`) REFERENCES `especialidades_v3` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_hist_mat_catalogo` FOREIGN KEY (`materia_id`) REFERENCES `materias_catalogo_v3` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_hist_materias_rel` FOREIGN KEY (`carga_historica_id`) REFERENCES `cargas_historicas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=562 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

