--
-- Table structure for table `docentes_datos_bancarios_v3`
--

DROP TABLE IF EXISTS `docentes_datos_bancarios_v3`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `docentes_datos_bancarios_v3` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `docente_id` int(10) unsigned NOT NULL,
  `banco_id` int(10) unsigned DEFAULT 1,
  `cuenta_bancaria` varchar(50) NOT NULL,
  `tipo_cuenta` enum('Ahorro','Corriente') NOT NULL DEFAULT 'Corriente',
  `es_principal` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_docente_id_cuenta` (`docente_id`,`cuenta_bancaria`),
